using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Preserve the old property name so existing documents are still readable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Id format changed from "EntityType|Key" to just "Key" in EF Core 9.
        // Preserve the old id format so existing documents (e.g. "Blog|1") are found.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Fix 3: HasIndex() now throws at runtime for Cosmos in EF Core 9.
        // Cosmos does automatic indexing; remove the unsupported HasIndex call.
        // (HasIndex call removed — was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name))
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Opt out of the new sync-I/O block if needed (EF Core 9 throws on sync calls by default).
        // Alternatively, convert all calls to async (see SyncJob.cs).
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

// Fix 2 (continued): Value generator that reproduces the EF Core 8 "Discriminator|Key" id format.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

